---@return string
---@param idProComp_ Game.Native.Common.IDPro 
---@param key_ string 
function IDProReader.ReadKeyValue( idProComp_, key_ )
    assert( not isNull(idProComp_) )
    assert( (type(key_) == "string") and (#key_ > 0) )

    assert( not isNull( idProComp_.keyValueList) )
    local len = idProComp_.keyValueList.Count
    assert( len > 0 )
    local ret = nil
    for i=0, len-1 do
        local p = idProComp_.keyValueList[i] -- List
        if (not isNull(p)) and (p.key == key_) then 
            ret = p.value
            break
        end
    end
    assert( not isNull(ret) )
    return ret
end



return IDProReader

